package app.tidecard;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.json.*;

/** Read-only carrier scope: switches UI languages and tests updates without applying SIM overrides. */
public final class LocalizationUpdateChecks {
    private final Instrumentation test;private final TideApp app;private final StringBuilder log=new StringBuilder();private final List<Activity> created=new java.util.concurrent.CopyOnWriteArrayList<>();private volatile Activity current;
    private final Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){created.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){current=a;}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
    public static void run(Instrumentation test,String candidate){new LocalizationUpdateChecks(test).run(candidate);}
    private LocalizationUpdateChecks(Instrumentation t){test=t;app=(TideApp)t.getTargetContext().getApplicationContext();}
    private interface Condition{boolean ok()throws Exception;}
    private void require(boolean ok,String reason){if(!ok)throw new AssertionError(reason);}
    private void main(Runnable work){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{work.run();}catch(Throwable t){error.set(t);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void waitFor(Condition condition,int ms,String reason)throws Exception{long end=System.currentTimeMillis()+ms;while(System.currentTimeMillis()<end){if(condition.ok()){test.waitForIdleSync();return;}Thread.sleep(100);}throw new AssertionError(reason);}
    private void note(String line){log.append(line).append('\n');Bundle b=new Bundle();b.putString("stream",line+"\n");test.sendStatus(0,b);}
    private void launch(Class<? extends Activity> type){main(()->app.startActivity(new Intent(app,type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP)));}
    private void capture(String name){main(()->{View root=current.getWindow().getDecorView();Bitmap image=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(image));try(FileOutputStream out=new FileOutputStream(new File(app.getExternalFilesDir(null),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new RuntimeException(e);}finally{image.recycle();}});}
    private JSONObject fixture()throws Exception{return new JSONObject().put("tag_name","v9.8.7").put("draft",false).put("prerelease",false).put("assets",new JSONArray().put(new JSONObject().put("name","TideCard-9.8.7.apk").put("browser_download_url",ReleaseInfo.REPO+"/releases/download/v9.8.7/TideCard-9.8.7.apk").put("digest","sha256:"+"a".repeat(64)).put("size",1234)));}
    private void rejected(JSONObject json)throws Exception{try{ReleaseInfo.parse(json);throw new AssertionError("Unsafe release accepted");}catch(IllegalArgumentException expected){}}
    private void run(String candidate){Map<String,?> before=new HashMap<>(app.prefs().getAll());String original=AppLanguage.mode(app);boolean passed=false;app.registerActivityLifecycleCallbacks(callbacks);
        try{
            note("No carrier writes; active="+app.active());launch(NotificationSettingsActivity.class);note("WAIT settings UI; foreground it with ADB if HyperOS blocks launch");for(int retry=0;retry<45&&!(current instanceof NotificationSettingsActivity);retry++){Thread.sleep(1000);if(!(current instanceof NotificationSettingsActivity))launch(NotificationSettingsActivity.class);}require(current instanceof NotificationSettingsActivity,"Settings did not open");
            String[] modes={"en","zh-Hant","zh-Hans","system"};int[] ids={R.id.language_english,R.id.language_traditional,R.id.language_simplified,R.id.language_system};
            for(int n=0;n<modes.length;n++){
                Activity old=current;int id=ids[n];main(()->old.findViewById(id).performClick());String mode=modes[n];waitFor(()->current!=old&&current instanceof NotificationSettingsActivity&&AppLanguage.mode(app).equals(mode),8000,"language recreation "+mode);
                String[] from=current.getResources().getStringArray(R.array.message_sources),to=current.getResources().getStringArray(R.array.message_translations);require(from.length==to.length&&from.length>=318,"catalog size");for(String item:to)require(!item.isEmpty(),"empty translation");
                require(((Button)current.findViewById(R.id.settings_update)).getText().toString().equals(I18n.tr("检查更新")),"settings label not localized");if(mode.equals("en")){require(I18n.tr("检查更新").equals("Check for updates"),"English resource");require(!I18n.message("恢复未完成：系统调用失败。原配置备份已保留，可重试停止。").matches(".*[\\p{IsHan}].*"),"canonical persisted error not translated");}if(mode.equals("zh-Hant"))require(I18n.tr("检查更新").equals("檢查更新"),"Traditional resource");
                capture("locale-settings-"+mode);launch(RegionPickerActivity.class);waitFor(()->current instanceof RegionPickerActivity,7000,"region picker");require(Regions.search("臺灣").stream().anyMatch(row->row[0].equals("tw")),"Traditional region search");capture("locale-dial-"+mode);main(()->current.finish());waitFor(()->current instanceof NotificationSettingsActivity,6000,"back to settings");note("PASS language "+mode+": resources, settings, dial, search");
            }
            require(ReleaseInfo.compare("2.10.0","2.9.9")>0&&ReleaseInfo.compare("v2.4.0","2.4.0")==0,"numeric version comparison");require(ReleaseInfo.parse(fixture()).version.equals("9.8.7"),"stable fixture");JSONObject bad=fixture();bad.put("prerelease",true);rejected(bad);bad=fixture();bad.getJSONArray("assets").getJSONObject(0).put("digest","");rejected(bad);bad=fixture();bad.getJSONArray("assets").getJSONObject(0).put("browser_download_url","http://github.com/DustinYe/TideCard-Android/releases/download/v9.8.7/TideCard-9.8.7.apk");rejected(bad);note("PASS reject prerelease, missing hash and insecure URL; numeric versions");
            if(candidate!=null){File file=new File(candidate);UpdateController.verifyApk(app.getPackageManager(),app.getPackageName(),file,"2.4.1");note("PASS real signed higher-version APK accepted");try{UpdateController.verifyApk(app.getPackageManager(),app.getPackageName(),file,"9.8.7");throw new AssertionError("Wrong version accepted");}catch(SecurityException expected){}note("PASS mismatched APK version rejected");File wrong=new File(file.getParentFile(),"update-test-wrong-signer.apk");if(wrong.exists()){try{UpdateController.verifyApk(app.getPackageManager(),app.getPackageName(),wrong,"2.4.1");throw new AssertionError("Wrong signing certificate accepted");}catch(SecurityException expected){require(expected.getMessage().contains("signing certificate"),"unexpected signer failure");}note("PASS same package/version with different signing certificate rejected");}}
            Activity settings=current;main(()->settings.findViewById(R.id.settings_update).performClick());waitFor(()->current instanceof UpdateActivity,6000,"update settings navigation");main(()->current.findViewById(R.id.update_check).performClick());waitFor(()->app.updates.state!=UpdateController.State.CHECKING,45000,"network check timeout");require(app.updates.state==UpdateController.State.CURRENT||app.updates.state==UpdateController.State.AVAILABLE,"GitHub check failed: "+app.updates.error);note("PASS real GitHub check: "+app.updates.release.version+" / "+app.updates.state);capture("locale-update-check");
            main(()->current.recreate());waitFor(()->current instanceof UpdateActivity&&current.findViewById(R.id.update_status)!=null,6000,"update recreation");require(app.updates.release!=null,"update state lost on recreation");
            // Download the actual public APK; the installed newer app must refuse it after hash validation.
            app.updates.state=UpdateController.State.AVAILABLE;main(()->app.updates.download());waitFor(()->app.updates.state!=UpdateController.State.DOWNLOADING,180000,"APK download timeout");require(app.updates.state==UpdateController.State.ERROR&&app.updates.error.equals("APK package or version mismatch"),"old APK not rejected after real download: "+app.updates.error);note("PASS live APK download, size/SHA verification, old-version rejection");capture("locale-update-reject-old");
            if(candidate!=null){File dir=new File(app.getFilesDir(),"updates");dir.mkdirs();File staged=new File(dir,"installer-fixture.apk");try(InputStream in=new FileInputStream(candidate);OutputStream out=new FileOutputStream(staged)){in.transferTo(out);}android.net.Uri uri=androidx.core.content.FileProvider.getUriForFile(app,app.getPackageName()+".updates",staged);try(InputStream in=app.getContentResolver().openInputStream(uri)){require(in.read()=='P'&&in.read()=='K',"APK provider could not read staged file");}note("PASS private APK content URI readable");
                JSONObject sample=fixture().put("tag_name","v2.4.1");JSONObject asset=sample.getJSONArray("assets").getJSONObject(0);asset.put("name","TideCard-2.4.1.apk").put("browser_download_url",ReleaseInfo.REPO+"/releases/download/v2.4.1/TideCard-2.4.1.apk");app.updates.release=ReleaseInfo.parse(sample);app.updates.ready=staged;app.updates.state=UpdateController.State.READY;main(()->app.changed());waitFor(()->current.findViewById(R.id.update_action).getVisibility()==View.VISIBLE,6000,"install action visibility");boolean allowed=app.getPackageManager().canRequestPackageInstalls();main(()->current.findViewById(R.id.update_action).performClick());Thread.sleep(500);android.view.accessibility.AccessibilityNodeInfo window=test.getUiAutomation().getRootInActiveWindow();if(window==null){note("WAIT installation prompt: host screenshot required on this ROM");Thread.sleep(10000);}else if(!allowed)require(!window.findAccessibilityNodeInfosByText(I18n.tr("允许安装更新")).isEmpty(),"unknown-sources permission explanation missing");else require(!app.getPackageName().contentEquals(window.getPackageName()),"system installer did not open");note("PASS installation handoff / permission explanation; no installation or permission grant performed");test.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);staged.delete();}
            passed=true;
        }catch(Throwable e){note("FAIL "+e);}
        finally{try{main(()->{for(Activity a:created)if(!a.isFinishing())a.finish();AppLanguage.set(app,original);});app.unregisterActivityLifecycleCallbacks(callbacks);require(before.equals(app.prefs().getAll()),"preferences or carrier-session state changed");note("PASS original language and all carrier preferences retained");}catch(Throwable e){note("CLEANUP FAIL "+e);passed=false;}Bundle result=new Bundle();result.putString("stream",log.toString());test.finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
    }
}
